function Get-InputText {
    if ($Text) {
        return [string]$Text
    }
    if ($Path) {
        return [string](Get-Content -LiteralPath $Path -Raw)
    }
    return [string](Get-Clipboard -Raw)
}

function Split-Params([string]$paramText) {
    $items = New-Object System.Collections.Generic.List[string]
    $current = New-Object System.Text.StringBuilder
    $inSingle = $false
    $inDouble = $false
    $depth = 0

    for ($i = 0; $i -lt $paramText.Length; $i++) {
        $ch = $paramText[$i]

        if ($ch -eq "'" -and -not $inDouble) {
            $inSingle = -not $inSingle
        }
        elseif ($ch -eq '"' -and -not $inSingle) {
            $inDouble = -not $inDouble
        }
        elseif (-not $inSingle -and -not $inDouble) {
            if ($ch -eq '(') {
                $depth++
            }
            elseif ($ch -eq ')' -and $depth -gt 0) {
                $depth--
            }
            elseif ($ch -eq ',' -and $depth -eq 0) {
                $items.Add($current.ToString().Trim())
                [void]$current.Clear()
                continue
            }
        }

        [void]$current.Append($ch)
    }

    $tail = $current.ToString().Trim()
    if ($tail) {
        $items.Add($tail)
    }

    return $items
}

function Format-Param([string]$token) {
    if ([string]::IsNullOrWhiteSpace($token)) {
        return 'NULL'
    }

    $m = [regex]::Match($token.Trim(), '^(?<value>.*?)(?:\((?<type>[^)]*)\))?$')
    $value = $m.Groups['value'].Value.Trim()
    $type = $m.Groups['type'].Value.Trim()

    if ($value -match '^(?i)null$') {
        return 'NULL'
    }
    if ($value -match '^''.*''$') {
        return $value
    }
    if ($value -match '^[+-]?\d+(\.\d+)?$') {
        return $value
    }
    if ($value -match '^(?i)(true|false)$') {
        return $value.ToLower()
    }

    if ($type -match '(?i)byte|short|int|long|bigdecimal|double|float|number') {
        if ($value -match '^[+-]?\d+(\.\d+)?$') {
            return $value
        }
    }

    $escaped = $value.Replace("'", "''")
    return "'" + $escaped + "'"
}

function Fill-Sql([string]$sql, [System.Collections.Generic.List[string]]$params) {
    $result = $sql
    foreach ($p in $params) {
        $formatted = Format-Param $p
        $parts = $result.Split('?', 2)
        if ($parts.Count -lt 2) {
            break
        }
        $result = $parts[0] + $formatted + $parts[1]
    }
    return $result
}

function Get-SqlText([string]$prefixText) {
    $prefixText = $prefixText.Trim()

    $lines = $prefixText -split '\r?\n'
    for ($i = $lines.Length - 1; $i -ge 0; $i--) {
        $line = $lines[$i].Trim()

        if ([string]::IsNullOrWhiteSpace($line)) {
            continue
        }

        if ($line -match '^(?i)(?:==>\s*)?Preparing:\s*') {
            return ($line -replace '^(?i)(?:==>\s*)?Preparing:\s*', '').Trim()
        }

        if ($line -match '^(?i)(?:==>\s*)?(select|update|delete|insert)\b') {
            return ($line -replace '^(?i)(?:==>\s*)?', '').Trim()
        }
    }

    return $null
}

$content = Get-InputText
if ([string]::IsNullOrWhiteSpace($content)) {
    throw "没有输入内容。请传 -Text、-Path，或者先把 SQL 日志复制到剪贴板。"
}

$content = $content.Trim()

$paramMatches = [regex]::Matches($content, '(?im)^\s*==>\s*Parameters:\s*(?<params>.+?)\s*$')
if ($paramMatches.Count -eq 0) {
    throw "没识别到 Parameters 日志。"
}

$lastParamMatch = $paramMatches[$paramMatches.Count - 1]
$paramText = $lastParamMatch.Groups['params'].Value.Trim()
$prefixText = $content.Substring(0, $lastParamMatch.Index)
$sqlText = Get-SqlText $prefixText

if ([string]::IsNullOrWhiteSpace($sqlText)) {
    throw "没识别到 SQL 语句。请确保 Parameters 前面有 select/update/delete/insert 或 Preparing: 开头的 SQL。"
}

$params = Split-Params $paramText
$filled = Fill-Sql $sqlText $params

